import { AccessibilityInfo, ActivityIndicator, Alert, AppState, Image, Linking, Modal, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, useColorScheme, View } from "react-native";
import * as Clipboard from "expo-clipboard";
