import QRCodeView from "react-native-qrcode-svg";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import {
  createCallbackURL, createDeveloperDeploymentCallback, createDexActionCallback, createSignedNativeTransfer, evmAddressFromYNX, parseDeveloperDeploymentDeepLink, parseDexActionDeepLink, parseExchangeOrderActionDeepLink, parseQuantActionDeepLink, parseWalletDeepLink, signAuthorization, signDeveloperDeployment, signDexAction, signExchangeOrderAction, signQuantAction, type AuthorizationRequest, type DeveloperDeploymentRequest, type DexActionRequest, type ExchangeOrderActionRequest, type QuantActionRequest,
} from "@ynx-chain/wallet-auth";
import { GatewaySecurityReviewProvider, SecurityReviewController, type ReviewSnapshot } from "./src/ai/securityReview";
import { NativeChainClient, type ChainAccount, type ChainActivity } from "./src/chain/nativeTransfer";
import { EvmSimulationClient, type EvmSimulationResult } from "./src/chain/evmSimulation";
import { buildWalletControlView, type CapitalReview } from "./src/control/controlSurface";
import { controlCopy } from "./src/control/controlCopy";
import { formatDateTime, formatYNXT, isRTL, loadLocale, localizeError, saveLocale, SUPPORTED_LOCALES, translate, type WalletLocale } from "./src/i18n/i18n";
import { AuthorizationAuditStore, type AuthorizationAuditRecord } from "./src/protocol/authorizationAudit";
import { PersistentNonceStore } from "./src/protocol/replayStore";
import { PRODUCT_REGISTRY, SCOPE_EXPLANATIONS } from "./src/protocol/registry";
import { WalletSessionInventoryClient, type WalletGatewayBridge, type WalletSessionInventory } from "./src/protocol/sessionInventory";
import { authorizeLocalKeyUse } from "./src/security/localAuthorization";
import { copyPublicValueWithExpiry } from "./src/security/clipboardPrivacy";
import { initialLockState, reduceLockState } from "./src/state/lockState";
