import { COLORS, DARK_COLORS, HIGH_CONTRAST_DARK, HIGH_CONTRAST_LIGHT } from "./src/theme";

let ACTIVE_COLORS=COLORS;
let styles=createStyles();
let MODAL_ANIMATION:"none"|"slide"="slide";
let ACCESSIBILITY_SUMMARY="System contrast · standard motion";

const repository=new WalletRepository(platformSecureStorage);
const nonces=new PersistentNonceStore(platformSecureStorage);
const authorizationAudit=new AuthorizationAuditStore(platformSecureStorage);
function chainClient(){const runtime=(globalThis as any).__YNX_WALLET_CHAIN_RUNTIME__ as {baseURL?:string;evmRpcURL?:string}|undefined;return new NativeChainClient(runtime?.baseURL)}
function evmSimulationClient(){const runtime=(globalThis as any).__YNX_WALLET_CHAIN_RUNTIME__ as {baseURL?:string;evmRpcURL?:string}|undefined;return new EvmSimulationClient(runtime?.evmRpcURL??runtime?.baseURL)}
function walletSessionInventoryClient(){const runtime=(globalThis as any).__YNX_WALLET_GATEWAY_RUNTIME__ as {request?:WalletGatewayBridge}|undefined;return runtime?.request?new WalletSessionInventoryClient(runtime.request):null}

export default function App(){return <SafeAreaProvider><WalletApp/></SafeAreaProvider>}

function WalletApp(){
  const colorScheme=useColorScheme();
  const [reducedMotion,setReducedMotion]=useState(false);
  const [highContrast,setHighContrast]=useState(false);
  ACTIVE_COLORS=highContrast?(colorScheme==="dark"?HIGH_CONTRAST_DARK:HIGH_CONTRAST_LIGHT):(colorScheme==="dark"?DARK_COLORS:COLORS);
  styles=createStyles();
  MODAL_ANIMATION=reducedMotion?"none":"slide";
  ACCESSIBILITY_SUMMARY=`${highContrast?"High":"System"} contrast · ${reducedMotion?"reduced":"standard"} motion · ${colorScheme==="dark"?"dark":"light"} appearance`;
  const [manifest,setManifest]=useState<WalletManifest|null>(null);
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState<string|null>(null);
  const [notice,setNotice]=useState<string|null>(null);
  const [lockState,dispatchLock]=useReducer(reduceLockState,undefined,initialLockState);
  const [onboarding,dispatchOnboarding]=useReducer(reduceOnboardingState,initialOnboardingState);
  const [authorization,setAuthorization]=useState<AuthorizationRequest|null>(null);
  const [exchangeAction,setExchangeAction]=useState<ExchangeOrderActionRequest|null>(null);
  const [developerDeployment,setDeveloperDeployment]=useState<DeveloperDeploymentRequest|null>(null);
  const [dexAction,setDexAction]=useState<DexActionRequest|null>(null);
  const [quantAction,setQuantAction]=useState<QuantActionRequest|null>(null);
  const [authorizationError,setAuthorizationError]=useState<string|null>(null);
  const [busy,setBusy]=useState(false);
  const [locale,setLocale]=useState<WalletLocale>("en");
  const [settings,setSettings]=useState(false);
  const [privacyAttempt,setPrivacyAttempt]=useState(0);
  const [privacyState,setPrivacyState]=useState<{ready:boolean;error:string|null}>({ready:false,error:null});
  const selected=useMemo(()=>manifest?.accounts.find((item)=>item.account===manifest.selectedAccountId)??null,[manifest]);

  const load=useCallback(async()=>{
    setLoading(true);setError(null);
    try{await assertSecureStorageAvailable();const [result,savedLocale]=await Promise.all([repository.load(),loadLocale(platformSecureStorage)]);setLocale(savedLocale);setManifest(result.manifest);if(result.migrated)setNotice("Existing secure identity migrated to the independent Wallet. The old product device key was discarded.");}
    catch(caught){setError(localizeError(locale,caught));}
    finally{setLoading(false)}
  },[locale]);

  const handleLink=useCallback((url:string)=>{
    try{const parsedURL=new URL(url);if(parsedURL.protocol==="ynxwallet:"&&parsedURL.hostname==="open"&&parsedURL.pathname===""&&!parsedURL.search&&!parsedURL.hash){setAuthorization(null);setExchangeAction(null);setDeveloperDeployment(null);setDexAction(null);setQuantAction(null)}else if(parsedURL.protocol==="ynxwallet:"&&parsedURL.hostname==="action"){setExchangeAction(parseExchangeOrderActionDeepLink(url,new Date()));setAuthorization(null);setDeveloperDeployment(null);setDexAction(null);setQuantAction(null)}else if(parsedURL.protocol==="ynxwallet:"&&parsedURL.hostname==="developer-deploy"){setDeveloperDeployment(parseDeveloperDeploymentDeepLink(url,new Date()));setAuthorization(null);setExchangeAction(null);setDexAction(null);setQuantAction(null)}else if(parsedURL.protocol==="ynxwallet:"&&parsedURL.hostname==="dex-action"){setDexAction(parseDexActionDeepLink(url,new Date()));setAuthorization(null);setExchangeAction(null);setDeveloperDeployment(null);setQuantAction(null)}else if(parsedURL.protocol==="ynxwallet:"&&parsedURL.hostname==="quant-action"){setQuantAction(parseQuantActionDeepLink(url,new Date()));setAuthorization(null);setExchangeAction(null);setDeveloperDeployment(null);setDexAction(null)}else{const parsed=parseWalletDeepLink(url,Platform.OS==="ios"?"ios":"android",{now:new Date(),registry:PRODUCT_REGISTRY});setAuthorization(parsed.request);setExchangeAction(null);setDeveloperDeployment(null);setDexAction(null);setQuantAction(null)}setAuthorizationError(null);}
    catch(caught){setAuthorization(null);setExchangeAction(null);setDeveloperDeployment(null);setDexAction(null);setQuantAction(null);setAuthorizationError(localizeError(locale,caught));}
  },[locale]);

  useEffect(()=>{void load();void Linking.getInitialURL().then((url)=>{if(url)handleLink(url)});const sub=Linking.addEventListener("url",({url})=>handleLink(url));return()=>sub.remove()},[handleLink,load]);
  useEffect(()=>{const sub=AppState.addEventListener("change",(next)=>{if(next!=="active"){dispatchLock({type:"lock",reason:"background"});dispatchOnboarding({type:"background"})}});return()=>sub.remove()},[]);
  useEffect(()=>{void AccessibilityInfo.isReduceMotionEnabled().then(setReducedMotion);void AccessibilityInfo.isHighTextContrastEnabled().then(setHighContrast);const sub=AccessibilityInfo.addEventListener("reduceMotionChanged",setReducedMotion);return()=>sub.remove()},[]);
  useEffect(()=>{let active=true;setPrivacyState({ready:false,error:null});void preventScreenCaptureAsync("wallet-runtime").then(()=>{if(active)setPrivacyState({ready:true,error:null})}).catch((caught)=>{if(active){dispatchLock({type:"lock",reason:"user"});setPrivacyState({ready:false,error:`Wallet privacy protection failed: ${message(caught)}`})}});return()=>{active=false;void allowScreenCaptureAsync("wallet-runtime")}},[privacyAttempt]);

  const unlock=async()=>{
    if(!selected)return;setBusy(true);setError(null);
    try{await authorizeLocalKeyUse("unlock");dispatchLock({type:"unlock",account:selected.account});}
    catch(caught){setError(localizeError(locale,caught))}finally{setBusy(false)}
  };
  const create=async()=>{const bytes=await getRandomBytesAsync(32);dispatchOnboarding({type:"openCreate",recoveryKey:bytesToHex(bytes),label:`Account ${(manifest?.accounts.length??0)+1}`})};
  const saved=(next:WalletManifest)=>{setManifest(next);dispatchOnboarding({type:"saveSucceeded"});dispatchLock({type:"lock",reason:"user"});setNotice("Account saved. Unlock with system biometrics to continue.")};
  const select=async(account:string)=>{try{const next=await repository.selectAccount(account);setManifest(next);dispatchLock({type:"switch",account})}catch(caught){setError(localizeError(locale,caught))}};

  if(!privacyState.ready)return privacyState.error?<Screen><Text style={styles.title}>Wallet privacy protection is required</Text><Text style={styles.error}>{privacyState.error}</Text><Button label="Retry screenshot protection" onPress={()=>setPrivacyAttempt((value)=>value+1)}/></Screen>:<Screen><ActivityIndicator color={ACTIVE_COLORS.blue}/><Text style={styles.muted}>Protecting Wallet screens</Text></Screen>;
  if(loading)return <Screen><ActivityIndicator color={ACTIVE_COLORS.blue}/><Text style={styles.muted}>Verifying secure Wallet storage</Text></Screen>;
  if(error&&manifest===null)return <Screen><Text style={styles.title}>Wallet storage needs attention</Text><Text style={styles.error}>{error}</Text><Button label="Retry secure storage" onPress={()=>void load()}/><DangerButton label="Reset unreadable local Wallet" onPress={()=>Alert.alert("Reset local Wallet?","Only continue if every account has an offline recovery key.",[{text:"Cancel",style:"cancel"},{text:"Reset",style:"destructive",onPress:()=>void repository.resetCorruptStorage().then(load)}])}/></Screen>;

  return <SafeAreaView edges={["top","left","right"]} style={[styles.safe,isRTL(locale)&&styles.rtl]}>
    <StatusBar style="auto"/>
    <View style={styles.header}><Image accessibilityLabel="YNX logo" source={require("./assets/ynx-logo.png")} resizeMode="contain" style={styles.brandLogo}/><View><Text style={styles.brand}>YNX Wallet</Text><Text style={styles.network}>YNX TESTNET · ynx_6423-1</Text></View><View style={styles.headerActions}><Pressable accessibilityLabel={translate(locale,"settingsTitle")} onPress={()=>setSettings(true)} style={styles.iconButton}><Languages size={19} color={ACTIVE_COLORS.ink}/></Pressable><Pressable accessibilityLabel={translate(locale,"lockWallet")} onPress={()=>dispatchLock({type:"lock",reason:"user"})} style={styles.iconButton}><Lock size={19} color={ACTIVE_COLORS.ink}/></Pressable></View></View>
    {notice?<Pressable accessibilityLabel="Dismiss Wallet notice" onPress={()=>setNotice(null)} style={styles.notice}><Text style={styles.noticeText}>{notice}</Text><X size={16} color={ACTIVE_COLORS.blue}/></Pressable>:null}
    {authorizationError?<View style={styles.bannerError}><Text style={styles.error}>{authorizationError}</Text><Pressable accessibilityLabel="Dismiss invalid authorization" onPress={()=>setAuthorizationError(null)}><X size={17} color={ACTIVE_COLORS.danger}/></Pressable></View>:null}
    {!manifest?.accounts.length
      ?<EmptyWallet locale={locale} create={()=>void create()} importAccount={()=>dispatchOnboarding({type:"openImport"})} recover={()=>dispatchOnboarding({type:"openRecover"})}/>
      :lockState.locked
        ?<Locked locale={locale} account={selected!} busy={busy} unlock={()=>void unlock()} recovery={()=>dispatchOnboarding({type:"openRecover"})}/>
        :<Dashboard locale={locale} manifest={manifest} selected={selected!} select={(account)=>void select(account)} add={()=>dispatchOnboarding({type:"openImport"})} create={()=>void create()} lock={()=>dispatchLock({type:"lock",reason:"user"})} onManifest={setManifest}/>}
    <SetupModal state={onboarding} dispatch={dispatchOnboarding} close={()=>{if(!busy)dispatchOnboarding({type:"close"})}} saved={saved} busy={busy} setBusy={setBusy} setError={setError}/>
    {authorization&&manifest&&selected?<AuthorizationModal locale={locale} key={authorization.nonce} request={authorization} selected={selected} close={()=>setAuthorization(null)} onApproved={()=>setAuthorization(null)}/>:null}
    {exchangeAction&&manifest&&selected?<ExchangeOrderActionModal key={exchangeAction.nonce} request={exchangeAction} selected={selected} close={()=>setExchangeAction(null)} onApproved={()=>setExchangeAction(null)}/>:null}
    {developerDeployment&&manifest&&selected?<DeveloperDeploymentModal key={developerDeployment.payload.requestHash} request={developerDeployment} selected={selected} close={()=>setDeveloperDeployment(null)} onApproved={()=>setDeveloperDeployment(null)}/>:null}
    {dexAction&&manifest&&selected?<DexActionModal key={`${dexAction.sessionBinding}:${dexAction.nonce}`} request={dexAction} selected={selected} close={()=>setDexAction(null)} onApproved={()=>setDexAction(null)}/>:null}
    {quantAction&&manifest&&selected?<QuantActionModal key={quantAction.nonce} request={quantAction} selected={selected} close={()=>setQuantAction(null)} onApproved={()=>setQuantAction(null)}/>:null}
    <LocaleSettings visible={settings} locale={locale} close={()=>setSettings(false)} select={(next)=>void saveLocale(platformSecureStorage,next).then(()=>setLocale(next))}/>
  </SafeAreaView>;
}

function EmptyWallet({locale,create,importAccount,recover}:{locale:WalletLocale;create:()=>void;importAccount:()=>void;recover:()=>void}){return <Screen><View style={styles.heroIcon}><KeyRound color={ACTIVE_COLORS.blue} size={34}/></View><Text style={styles.eyebrow}>{translate(locale,"welcome")}</Text><Text style={styles.title}>{translate(locale,"ownAccount")}</Text><Text style={styles.centerText}>{translate(locale,"privacy")}</Text><Button label={translate(locale,"createWallet")} onPress={create}/><SecondaryButton label={translate(locale,"importWallet")} onPress={importAccount}/><SecondaryButton label={translate(locale,"recoverReplacement")} onPress={recover}/><InfoCard title={translate(locale,"beforeBegin")} body={translate(locale,"recovery")}/></Screen>}

function Locked({locale,account,busy,unlock,recovery}:{locale:WalletLocale;account:WalletAccount;busy:boolean;unlock:()=>void;recovery:()=>void}){return <Screen><View style={styles.heroIcon}><Lock color={ACTIVE_COLORS.blue} size={32}/></View><Text style={styles.eyebrow}>{translate(locale,"walletLocked")}</Text><Text style={styles.title}>{account.label}</Text><Text style={styles.address}>{short(account.account)}</Text><Button label={busy?translate(locale,"checkingBiometrics"):translate(locale,"unlock")} disabled={busy} onPress={unlock} icon={<Fingerprint color={ACTIVE_COLORS.white} size={19}/>}/><SecondaryButton label={translate(locale,"lostDeviceRecovery")} onPress={recovery}/><Text style={styles.footnote}>{translate(locale,"recovery")}</Text></Screen>}

function Dashboard({locale,manifest,selected,select,add,create,lock,onManifest}:{locale:WalletLocale;manifest:WalletManifest;selected:WalletAccount;select:(v:string)=>void;add:()=>void;create:()=>void;lock:()=>void;onManifest:(v:WalletManifest)=>void}){
  const [accountsOpen,setAccountsOpen]=useState(false),[copied,setCopied]=useState(false),[qr,setQR]=useState(false),[send,setSend]=useState(false),[evm,setEvm]=useState(false),[center,setCenter]=useState(false),[controls,setControls]=useState(false),[remove,setRemove]=useState(false),[rename,setRename]=useState(false),[recovery,setRecovery]=useState(false),[auditOpen,setAuditOpen]=useState(false),[records,setRecords]=useState<readonly AuthorizationAuditRecord[]>([]),[auditError,setAuditError]=useState<string|null>(null);
  const cancelClipboardClear=useRef<null|(()=>void)>(null);
  const [chainState,setChainState]=useState<{phase:"loading"|"ready"|"failed";account?:ChainAccount;activity:readonly ChainActivity[];error?:string}>({phase:"loading",activity:[]});
  const refreshChain=useCallback(async()=>{setChainState((state)=>({phase:"loading",account:state.account,activity:state.activity}));try{const client=chainClient();const[account,activity]=await Promise.all([client.account(selected.account),client.activity(selected.account)]);setChainState({phase:"ready",account,activity})}catch(caught){setChainState((state)=>({phase:"failed",account:state.account,activity:state.activity,error:message(caught)}))}},[selected.account]);
  useEffect(()=>{void refreshChain()},[refreshChain]);
  const copy=async()=>{cancelClipboardClear.current?.();cancelClipboardClear.current=await copyPublicValueWithExpiry(Clipboard,selected.account);setCopied(true);setTimeout(()=>setCopied(false),1500)};
  const openAudit=async()=>{setAuditError(null);try{setRecords(await authorizationAudit.load());setAuditOpen(true)}catch(caught){setAuditError(localizeError(locale,caught));setAuditOpen(true)}};
  const revoke=async(record:AuthorizationAuditRecord)=>{try{await authorizeLocalKeyUse("wallet-authorization");await authorizationAudit.revoke(record.requestDigest,new Date().toISOString());setRecords(await authorizationAudit.load())}catch(caught){setAuditError(localizeError(locale,caught))}};
  return <ScrollView contentContainerStyle={styles.dashboard}>
    <Text style={styles.eyebrow}>{translate(locale,"nativeAccount")}</Text>
    <Pressable accessibilityLabel="Switch Wallet account" accessibilityState={{expanded:accountsOpen}} onPress={()=>setAccountsOpen(!accountsOpen)} style={styles.accountPicker}><View><Text style={styles.accountLabel}>{selected.label}</Text><Text style={styles.address}>{short(selected.account)}</Text></View><ChevronDown color={ACTIVE_COLORS.ink}/></Pressable>
    {accountsOpen?<View style={styles.accountMenu}>{manifest.accounts.map((item)=><Pressable accessibilityRole="radio" accessibilityState={{checked:item.account===selected.account}} accessibilityLabel={`${translate(locale,"account")} ${item.label}`} key={item.account} onPress={()=>{select(item.account);setAccountsOpen(false)}} style={styles.accountRow}><View><Text style={styles.accountLabel}>{item.label}</Text><Text style={styles.smallAddress}>{short(item.account)}</Text></View>{item.account===selected.account?<Check color={ACTIVE_COLORS.blue}/>:null}</Pressable>)}<Pressable accessibilityLabel={translate(locale,"createAnother")} onPress={create} style={styles.accountRow}><Plus color={ACTIVE_COLORS.blue}/><Text style={styles.link}>{translate(locale,"createAnother")}</Text></Pressable><Pressable accessibilityLabel={translate(locale,"importAnother")} onPress={add} style={styles.accountRow}><KeyRound color={ACTIVE_COLORS.blue}/><Text style={styles.link}>{translate(locale,"importAnother")}</Text></Pressable></View>:null}
    <View style={styles.balanceCard}><Text style={styles.balanceLabel}>Native asset · authoritative testnet</Text><Text style={styles.balance}>{chainState.account?formatYNXT(locale,chainState.account.balance):"— YNXT"}</Text><Text style={styles.balanceMeta}>{chainState.phase==="loading"?"Loading balance and nonce from rpc.ynxweb4.com…":chainState.phase==="failed"?`Network unavailable: ${chainState.error}`:`Nonce ${chainState.account?.nonce??0} · ${chainState.activity.length} recent account transaction${chainState.activity.length===1?"":"s"}`}</Text></View>
    <View style={styles.quickRow}><Quick icon={<ArrowUpRight color={ACTIVE_COLORS.blue}/>} label={translate(locale,"send")} onPress={()=>setSend(true)}/><Quick icon={<QrCode color={ACTIVE_COLORS.blue}/>} label={translate(locale,"receive")} onPress={()=>setQR(true)}/><Quick icon={<History color={ACTIVE_COLORS.blue}/>} label={translate(locale,"activity")} onPress={()=>setCenter(true)}/></View>
    <InfoCard title={translate(locale,"accountSafety")} body={selected.backupConfirmed?"Offline backup confirmed. System biometrics protect unlock, authorization, recovery viewing and deletion.":"Backup is not confirmed. Do not receive assets until the recovery key is stored offline."}/>
    <SecondaryButton label={copied?"Native ynx1 address copied":"Copy native ynx1 address"} onPress={()=>void copy()}/>
    <SecondaryButton label="Rename account" onPress={()=>setRename(true)}/>
    <SecondaryButton label="View offline recovery key" onPress={()=>setRecovery(true)}/>
    <SecondaryButton label="0x EVM compatibility and contract simulation" onPress={()=>setEvm(true)}/>
    <SecondaryButton label="Connected Apps, Sessions and Devices" onPress={()=>setCenter(true)}/>
    <SecondaryButton label={controlCopy(locale,"open")} onPress={()=>setControls(true)}/>
    <SecondaryButton label={translate(locale,"lockWallet")} onPress={lock}/>
    <SecondaryButton label={translate(locale,"audit")} onPress={()=>void openAudit()}/>
    <DangerButton label="Remove account from this device" onPress={()=>setRemove(true)}/>
    <Modal visible={qr} transparent animationType={MODAL_ANIMATION} onRequestClose={()=>setQR(false)}><Sheet title="Receive YNXT" close={()=>setQR(false)}><View style={styles.qr}><QRCodeView value={`ynx:${selected.account}?chainId=ynx_6423-1&asset=YNXT`} size={210} color={ACTIVE_COLORS.ink} backgroundColor={ACTIVE_COLORS.white}/></View><Text selectable style={styles.fullAddress}>{selected.account}</Text><Text style={styles.footnote}>Native network ynx_6423-1 · EVM chain ID 6423. An 0x address is shown only inside an explicit EVM compatibility view.</Text></Sheet></Modal>
    <SendModal visible={send} account={selected} close={()=>setSend(false)} onSent={()=>void refreshChain()}/>
    <EvmCompatibilityModal visible={evm} account={selected} close={()=>setEvm(false)}/>
    <WalletCenter visible={center} account={selected} chainState={chainState} close={()=>setCenter(false)} openAudit={()=>void openAudit()} retry={()=>void refreshChain()}/>
    <WalletControlCenter visible={controls} locale={locale} close={()=>setControls(false)}/>
    <RecoveryExportModal visible={recovery} account={selected} close={()=>setRecovery(false)}/>
    <Modal visible={auditOpen} transparent animationType={MODAL_ANIMATION} onRequestClose={()=>setAuditOpen(false)}><Sheet title={translate(locale,"audit")} close={()=>setAuditOpen(false)}>{auditError?<Text style={styles.error}>{auditError}</Text>:null}{records.length===0?<Text style={styles.sheetText}>No authorization decisions are stored on this device.</Text>:records.slice().reverse().map((record)=><View key={record.hash} style={styles.auditRow}><Text style={styles.infoTitle}>{record.action} · {record.productClientId}</Text><Text style={styles.infoBody}>{formatDateTime(locale,record.at)} · {short(record.account)}{"\n"}{record.scopes.join(", ")}</Text>{record.action==="approval-returned"&&!records.some((item)=>item.action==="approval-revoked"&&item.requestDigest===record.requestDigest)?<SecondaryButton label={translate(locale,"revoke")} onPress={()=>void revoke(record)}/>:null}</View>)}</Sheet></Modal>
    <DeleteModal visible={remove} account={selected} close={()=>setRemove(false)} deleted={(next)=>{setRemove(false);onManifest(next)}}/>
    <RenameModal visible={rename} account={selected} close={()=>setRename(false)} renamed={(next)=>{setRename(false);onManifest(next)}}/>
  </ScrollView>
}

function SetupModal({state,dispatch,close,saved,busy,setBusy,setError}:{state:OnboardingState;dispatch:React.Dispatch<Parameters<typeof reduceOnboardingState>[1]>;close:()=>void;saved:(v:WalletManifest)=>void;busy:boolean;setBusy:(v:boolean)=>void;setError:(v:string|null)=>void}){
  const persist=async()=>{let saving:OnboardingState;try{saving=beginOnboardingSave(state)}catch(caught){setError(message(caught));return}dispatch({type:"beginSave"});setBusy(true);try{if(saving.mode!=="create")await authorizeLocalKeyUse("account-import");saved(await repository.addAccount(onboardingAccountInput(saving,new Date().toISOString())))}catch(caught){dispatch({type:"saveFailed"});setError(message(caught))}finally{setBusy(false)}};
  return <Modal visible={state.mode!=="closed"} transparent animationType={MODAL_ANIMATION} onRequestClose={close}>{state.mode==="create"?<RecoverySheet pending={{secretHex:state.recoveryKey,label:state.label}} confirmation={state.backupConfirmation} setConfirmation={(value)=>dispatch({type:"editBackupConfirmation",value})} busy={busy} save={()=>void persist()} close={close}/>:<Sheet title={state.mode==="recover"?"Recover Wallet":"Import account"} close={close}><Text style={styles.sheetText}>{state.mode==="recover"?"Replacement-device recovery restores only the native account. Connected Apps, sessions, device approvals and audit history must be re-created.":"Enter a 64-character YNX recovery key. Import requires system biometrics and does not restore product device sessions."}</Text><Field label="Account label" value={state.label} onChangeText={(value)=>dispatch({type:"editLabel",value})}/><Field label="Recovery key" value={state.recoveryKey} onChangeText={(value)=>dispatch({type:"editRecoveryKey",value})} secure multiline/><Button label={state.mode==="recover"?"Recover into secure storage":"Import into secure storage"} disabled={busy||!canSaveOnboarding(state)} onPress={()=>void persist()}/></Sheet>}</Modal>
}

function SendModal({visible,account,close,onSent}:{visible:boolean;account:WalletAccount;close:()=>void;onSent:()=>void}){const[to,setTo]=useState(""),[amount,setAmount]=useState(""),[review,setReview]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState<string|null>(null),[success,setSuccess]=useState<string|null>(null);useEffect(()=>{if(!visible){setTo("");setAmount("");setReview(false);setError(null);setSuccess(null)}},[visible]);let valid=false;try{valid=evmAddressFromYNX(to)!==evmAddressFromYNX(account.account)&&/^\d+$/.test(amount)&&Number.isSafeInteger(Number(amount))&&Number(amount)>0}catch{valid=false}const submit=async()=>{setBusy(true);setError(null);try{await authorizeLocalKeyUse("transaction-sign");const client=chainClient();const remote=await client.account(account.account);const value=Number(amount);if(remote.balance<value+1)throw new Error(`Insufficient YNXT: ${value} amount + 1 network fee exceeds ${remote.balance}`);const secret=await repository.accountSecret(account.account);const signed=createSignedNativeTransfer({accountSecret:secret,to,amount:value,nonce:remote.nonce+1});const result=await client.broadcast(signed.payload,signed.transaction,signed.hash);setSuccess(result.hash);onSent()}catch(caught){setError(message(caught))}finally{setBusy(false)}};return <Modal visible={visible} transparent animationType={MODAL_ANIMATION} onRequestClose={close}><Sheet title={success?"Transfer Submitted":review?"Send Review":"Send YNXT"} close={close}>{success?<><View style={styles.heroIcon}><Check color={ACTIVE_COLORS.success} size={34}/></View><Text style={styles.sheetText}>The authoritative YNX testnet accepted the signature-verified native transfer.</Text><ReviewRow label="Transaction" value={success}/><Button label="Done" onPress={close}/></>:review?<><ReviewRow label="From" value={`${account.label}\n${short(account.account)}`}/><ReviewRow label="To" value={to}/><ReviewRow label="Amount" value={`${amount} YNXT`}/><ReviewRow label="Network fee" value="1 YNXT"/><ReviewRow label="Network" value="ynx_6423-1"/><InfoCard title="Final biometric confirmation" body="Wallet will fetch the current authoritative nonce and balance, sign the exact canonical transfer, and POST it only to the configured YNX RPC origin."/>{error?<Text style={styles.error}>{error}</Text>:null}<SecondaryButton label="Edit transfer" disabled={busy} onPress={()=>setReview(false)}/><Button label={busy?"Signing and broadcasting…":"Sign and broadcast"} disabled={busy} onPress={()=>void submit()}/></>:<><Text style={styles.sheetText}>Enter a native ynx1 address and whole-number YNXT amount. The 0x wire identity stays inside the canonical transaction implementation and is not the default UI.</Text><Field label="Recipient ynx1 address" value={to} onChangeText={setTo}/><Field label="Whole YNXT amount" value={amount} onChangeText={setAmount}/><Button label="Review transfer" disabled={!valid} onPress={()=>setReview(true)}/></>}</Sheet></Modal>}

function EvmCompatibilityModal({visible,account,close}:{visible:boolean;account:WalletAccount;close:()=>void}){const from=evmAddressFromYNX(account.account);const[to,setTo]=useState(""),[data,setData]=useState("0x"),[valueWei,setValueWei]=useState("0"),[busy,setBusy]=useState(false),[copied,setCopied]=useState(false),[result,setResult]=useState<EvmSimulationResult|null>(null),[error,setError]=useState<string|null>(null);useEffect(()=>{if(!visible){setTo("");setData("0x");setValueWei("0");setBusy(false);setCopied(false);setResult(null);setError(null)}},[visible]);const valid=/^0x[0-9a-f]{40}$/.test(to)&&to!==from&&/^0x(?:[0-9a-f]{2})*$/.test(data)&&/^(0|[1-9][0-9]{0,77})$/.test(valueWei);const copy=async()=>{await copyPublicValueWithExpiry(Clipboard,from);setCopied(true);setTimeout(()=>setCopied(false),1500)};const simulate=async()=>{setBusy(true);setError(null);setResult(null);try{setResult(await evmSimulationClient().simulate({from,to,data,valueWei}))}catch(caught){setError(message(caught))}finally{setBusy(false)}};return <Modal visible={visible} transparent animationType={MODAL_ANIMATION} onRequestClose={close}><Sheet title="0x EVM compatibility" close={close}><ReviewRow label="Default Wallet identity" value={account.account}/><ReviewRow label="Derived 0x address" value={from}/><SecondaryButton label={copied?"0x address copied for 30 seconds":"Copy 0x address for 30 seconds"} onPress={()=>void copy()}/><InfoCard title="Read-only simulation boundary" body="Wallet verifies chain ID 6423, deployed contract code, eth_call and eth_estimateGas. This view never signs or broadcasts an EVM transaction."/><Field label="Contract address (lowercase 0x)" value={to} onChangeText={(value)=>{setTo(value.trim());setResult(null)}}/><Field label="Calldata (lowercase even-length hex)" value={data} onChangeText={(value)=>{setData(value.trim());setResult(null)}} multiline/><Field label="Native value in wei" value={valueWei} onChangeText={(value)=>{setValueWei(value.trim());setResult(null)}}/>{error?<Text style={styles.error}>{error}</Text>:null}{result?<><Text style={[styles.eyebrow,styles.sectionLabel]}>PRECISE SIMULATION REVIEW</Text><ReviewRow label="Status" value={result.truthfulStatus}/><ReviewRow label="Chain / block" value={`${result.chainId} / ${result.blockNumber}`}/><ReviewRow label="From" value={result.from}/><ReviewRow label="Contract" value={result.to}/><ReviewRow label="Method selector" value={result.methodSelector}/><ReviewRow label="Value" value={`${result.valueWei} wei`}/><ReviewRow label="Gas estimate" value={result.gasEstimate}/><ReviewRow label="Code" value={`${result.contractCodeBytes} bytes\n${result.contractCodeHash}`}/><ReviewRow label="Return data" value={result.returnData}/><ReviewRow label="Source / as of" value={`${result.source}\n${result.asOf}`}/><InfoCard title="Simulation is not execution" body="State, gas, code and return values can change before a separately reviewed transaction is signed. No success, settlement or receipt is claimed here."/></>:null}<Button label={busy?"Verifying RPC and simulating…":"Run read-only contract simulation"} disabled={busy||!valid} onPress={()=>void simulate()}/></Sheet></Modal>}

function WalletCenter({visible,account,chainState,close,openAudit,retry}:{visible:boolean;account:WalletAccount;chainState:{phase:"loading"|"ready"|"failed";account?:ChainAccount;activity:readonly ChainActivity[];error?:string};close:()=>void;openAudit:()=>void;retry:()=>void}){
  const [inventory,setInventory]=useState<{phase:"idle"|"loading"|"ready"|"failed";value?:WalletSessionInventory;error?:string}>({phase:"idle"});
  const refreshInventory=useCallback(async()=>{const client=walletSessionInventoryClient();if(!client){setInventory({phase:"failed",error:"Canonical Gateway Wallet-control proof bridge is not connected."});return}setInventory({phase:"loading"});try{setInventory({phase:"ready",value:await client.load(account.account)})}catch(caught){setInventory({phase:"failed",error:message(caught)})}},[account.account]);
  useEffect(()=>{if(visible)void refreshInventory();else setInventory({phase:"idle"})},[visible,refreshInventory]);
  return <Modal visible={visible} transparent animationType={MODAL_ANIMATION} onRequestClose={close}><Sheet title="Wallet Center" close={close}><Text style={styles.eyebrow}>ASSETS / ACTIVITY</Text><InfoCard title={chainState.account?`${chainState.account.balance} YNXT`:chainState.phase==="loading"?"YNXT · loading":"YNXT · unavailable"} body={chainState.phase==="failed"?chainState.error??"Network unavailable":`Authoritative nonce ${chainState.account?.nonce??0} on ynx_6423-1.`}/>{chainState.activity.length===0?<InfoCard title="Activity · empty" body={chainState.phase==="ready"?"No recent authoritative transactions involve this account.":"Activity requires the authoritative testnet API."}/>:chainState.activity.map((item)=><View key={item.hash} style={styles.auditRow}><Text style={styles.infoTitle}>{item.to===evmAddressFromYNX(account.account)?"Received":"Sent"} · {item.amount} YNXT</Text><Text style={styles.infoBody}>{short(item.hash)} · fee {item.fee} · nonce {item.nonce}</Text></View>)}{chainState.phase==="failed"?<SecondaryButton label="Retry authoritative network" onPress={retry}/>:null}<Text style={[styles.eyebrow,styles.sectionLabel]}>CONNECTED APPS / SESSIONS / DEVICES</Text>{inventory.phase==="loading"?<InfoCard title="Connected Apps · loading" body="Requesting a fresh account-bound inventory through the canonical Wallet Product Session proof bridge."/>:inventory.phase==="failed"?<><InfoCard title="Connected Apps · unavailable" body={inventory.error??"Canonical Gateway inventory failed closed."}/><SecondaryButton label="Retry Connected Apps inventory" onPress={()=>void refreshInventory()}/></>:inventory.value&&inventory.value.connectedApps.length?<><ReviewRow label="Gateway evidence" value={`${inventory.value.asOf}\n${inventory.value.sessions.length} sessions · ${inventory.value.devices.length} devices · ${inventory.value.approvalCount} approvals`}/>{inventory.value.connectedApps.map((item)=><View key={`${item.productClientId}:${item.bundleId}`} style={styles.auditRow}><Text style={styles.infoTitle}>{item.requestingProduct} · {item.active?"ACTIVE":"INACTIVE"}</Text><Text style={styles.infoBody}>{item.productClientId}{"\n"}{item.activeSessionBindings.length}/{item.sessionBindings.length} active sessions · {item.deviceBindings.length} devices</Text></View>)}</>:<InfoCard title="Connected Apps · empty" body="The fresh canonical Gateway inventory contains no Product Sessions for this account."/>}<InfoCard title="Device security boundary" body={`Native account ${short(account.account)} remains protected by device-only secure storage and system biometrics. Gateway status never grants asset authority.`}/><SecondaryButton label="Open Authorization Audit" onPress={openAudit}/><Text style={[styles.eyebrow,styles.sectionLabel]}>RECOVERY / SECURITY / AUDIT / NETWORK</Text><InfoCard title="Recovery" body="The offline recovery key restores the native account only. Product devices and sessions are deliberately excluded."/><InfoCard title="Security" body="Wallet locks on background and requires biometrics for private-key use. Recovery display blocks screen capture."/><InfoCard title="Network" body="YNX testnet · ynx_6423-1 · native YNXT · rpc.ynxweb4.com. EVM chain ID 6423 is an advanced compatibility view only."/></Sheet></Modal>
}

